$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new();$first=Get-CimInstance Win32_Process -Filter 'ProcessId=30352';$second=Get-CimInstance Win32_Process -Filter 'ProcessId=16616';if($null -eq $first -or $null -eq $second){throw 'CIM snapshot missing'};[Console]::WriteLine('SNAPSHOT_READY');[Console]::ReadLine()|Out-Null;$rows=@(@($first,$second) | ForEach-Object { try { $p=Get-Process -Id $_.ProcessId -ErrorAction Stop } catch { if ($_.FullyQualifiedErrorId -like 'NoProcessFoundForGivenId,*') { exit 75 }; throw }; [pscustomobject]@{pid=[int]$_.ProcessId; parent_pid=[int]$_.ParentProcessId; creation_filetime=[string]$p.StartTime.ToFileTimeUtc(); name=$_.Name; command_line=$_.CommandLine; executable=$_.ExecutablePath; title=$p.MainWindowTitle} }); ConvertTo-Json -InputObject $rows -Compress -Depth 4